from _lib import *
lesson("wish-if-only-would-rather", "Tryby nierzeczywiste", "Wish, if only, would rather, it's time", 4,
 "Po wish, if only, would rather (z innym podmiotem) i it's (high) time używamy czasu 'o krok wstecz', aby wyrazić sytuację nierzeczywistą: past simple dla teraźniejszości, past perfect dla przeszłości, would + bezokolicznik dla irytacji lub życzenia zmiany czyjegoś zachowania.",
 "Te struktury wyrażają żal, pretensje, preferencje i sugestie. Są bardzo częste w Part 4 (np. I regret… → I wish I had…; You should… → It's time you…).",
 dict(scheme="wish/if only + past simple (teraz) | + past perfect (przeszłość) | + would (irytacja/zmiana)  •  would rather + bezokolicznik (ten sam podmiot) | + podmiot + past simple  •  it's time + podmiot + past simple", word_order="I wish I knew. / If only I had listened. / I'd rather you didn't smoke. / It's time we left.",
      affirmative=["I wish I lived closer to the sea.", "If only I had kept the receipt.", "I'd rather stay at home tonight."],
      negative=["I wish you wouldn't interrupt me.", "I'd rather you didn't tell anyone.", "I wish I hadn't said that."],
      questions=["Would you rather we met tomorrow?", "Don't you wish you had more free time?"]),
 [X("I wish I spoke Spanish.", "Szkoda, że nie mówię po hiszpańsku.", "Teraz → past simple."),
  X("I wish I had studied harder at school.", "Żałuję, że nie uczyłem się pilniej w szkole.", "Przeszłość → past perfect."),
  X("I wish you would stop complaining.", "Chciałbym, żebyś przestał narzekać.", "Irytacja zachowaniem innej osoby → would."),
  X("If only it weren't raining.", "Gdyby tylko nie padało.", "If only = mocniejsze wish; were w stylu formalnym."),
  X("If only I hadn't sold my bike.", "Gdybym tylko nie sprzedał roweru.", "Żal dotyczący przeszłości."),
  X("I'd rather walk than take the bus.", "Wolę iść pieszo, niż jechać autobusem.", "Ten sam podmiot → bezokolicznik bez to."),
  X("I'd rather you came a bit earlier.", "Wolałbym, żebyś przyszedł trochę wcześniej.", "Inny podmiot → past simple."),
  X("I'd rather you hadn't told her.", "Wolałbym, żebyś jej tego nie mówił.", "Preferencja dotycząca przeszłości → past perfect."),
  X("It's time we went home.", "Czas, żebyśmy poszli do domu.", "It's time + podmiot + past simple."),
  X("It's high time the government did something about it.", "Najwyższy czas, żeby rząd coś z tym zrobił.", "High time wzmacnia pilność."),
  X("It's time to go.", "Czas iść.", "Bez podmiotu → to + bezokolicznik.")],
 [C("wish + past simple vs wish + would", "Past simple – stan, którego nie możemy zmienić (I wish I were taller). Would – czyjeś zachowanie, które chcemy zmienić.", "Nie mówimy I wish I would… o sobie (wyjątek: rzadkie przypadki postanowień)."),
  C("wish vs hope", "Hope – coś realnego, możliwego: I hope you pass. Wish – nierzeczywiste.", "Jeśli coś może się zdarzyć – hope."),
  C("would rather vs prefer", "Would rather + bezokolicznik bez to; prefer + -ing/to + bezokolicznik.", "I'd rather walk = I prefer walking.")],
 [W("I wish I would have more time.", "I wish I had more time.", "Dla stanów u siebie – past simple."),
  W("I wish I didn't go there yesterday.", "I wish I hadn't gone there yesterday.", "Przeszłość wymaga past perfect."),
  W("I'd rather you don't smoke here.", "I'd rather you didn't smoke here.", "Po would rather + inny podmiot – past simple."),
  W("It's time we go.", "It's time we went.", "Po it's time + podmiot – past simple."),
  W("I'd rather to stay.", "I'd rather stay.", "Would rather + bezokolicznik bez to.")],
 ["Po wish z I/he/she/it w stylu formalnym używamy were: I wish I were there.",
  "Wish + rzeczownik/bezokolicznik oznacza 'chcieć' (formalnie): I wish to complain.",
  "Would sooner ma to samo znaczenie co would rather."],
 [dict(en="Many voters now wish they had paid closer attention to the campaign.", pl="Wielu wyborców żałuje teraz, że nie śledziło uważniej kampanii.", note="Wish w sprawozdawczym, esejowym kontekście."),
  dict(en="It is high time policymakers acknowledged the scale of the problem.", pl="Najwyższy czas, by decydenci przyznali, jak duży jest problem.", note="Mocne zdanie do zakończenia eseju."),
  dict(en="I would rather the committee postponed the decision than rushed it.", pl="Wolałbym, żeby komisja odłożyła decyzję, niż ją pospieszyła.", note="Would rather + podmiot + past simple … than …")],
 [G("I wish I ___ (have) a car – the buses are terrible.", ["had"], "Teraz → past simple."),
  G("If only I ___ (not / eat) so much last night.", ["hadn't eaten", "had not eaten"], "Przeszłość → past perfect."),
  G("I wish my neighbours ___ (stop) playing loud music.", ["would stop"], "Irytacja zachowaniem innych → would."),
  M("I'd rather you ___ your phone during dinner.", ["didn't use", "don't use", "not use", "wouldn't use"], "didn't use", "Inny podmiot → past simple.", {"don't use": "Czas teraźniejszy nie pasuje po would rather + podmiot.", "not use": "Brak operatora.", "wouldn't use": "Would nie stoi po would rather."}),
  G("It's high time you ___ (find) a job.", ["found"], "It's time + podmiot + past simple."),
  K("I regret not going to university.", "WISH", "I ___ to university.", ["wish I had gone", "wish that I had gone"], "Żal → wish + past perfect."),
  K("I'd prefer you not to call me at work.", "RATHER", "I'd ___ me at work.", ["rather you didn't call", "rather you did not call"], "Would rather + podmiot + past simple."),
  E("I wish I can swim.", ["I wish I could swim.", "could swim"], "Can → could po wish.")],
 [K("You should go to bed now, children.", "TIME", "It's ___ to bed, children.", ["time you went", "high time you went"], "It's time + you + past simple."),
  K("It's a pity I don't know the answer.", "ONLY", "If ___ the answer.", ["only I knew"], "If only + past simple."),
  K("Please stop interrupting me.", "WISH", "I ___ interrupting me.", ["wish you would stop", "wish you'd stop"], "Wish + would dla cudzego zachowania."),
  G("I'd rather ___ (stay) in tonight, if you don't mind.", ["stay"], "Ten sam podmiot → bezokolicznik bez to."),
  M("I wish I ___ that – I've upset her.", ["hadn't said", "didn't say", "wouldn't say", "haven't said"], "hadn't said", "Żal dotyczący przeszłości.", {"didn't say": "Past simple po wish dotyczy teraźniejszości.", "wouldn't say": "Would dotyczy zmiany zachowania w przyszłości.", "haven't said": "Present perfect nie występuje po wish."}),
  T("Szkoda, że nie ma cię tutaj.", ["I wish you were here.", "I wish you were here with me.", "If only you were here."], "Wish + past simple (were).")])
